import{B,C,read,path}from'../ten-utils.js';import{energyLevels,fmt10}from'../ten-math.js';
export default({g,p,extra,t})=>{let m=extra.mode??0,k=p[0];if(m===0){let e=energyLevels(k),labels=[B('Producers','उत्पादक'),B('Primary consumers','प्राथमिक उपभोक्ता'),B('Secondary consumers','द्वितीयक उपभोक्ता'),B('Tertiary consumers','तृतीयक उपभोक्ता')];g.bars({title:B('Approximate energy transfer','ऊर्जा का लगभग स्थानांतरण'),max:k,items:e.map((v,i)=>({label:labels[i],value:v,color:[C.green,C.gold,C.blue,C.pink][i],unit:'J'}))});return e.map((v,i)=>read(labels[i].en,labels[i].hi,fmt10(v),'J'))}
if(m===1){let factors=[1,3,10,30];for(let j=0;j<4;j++){g.sphere(-1.2+j*.8,0,0,.1+j*.05,j===k-1?C.gold:C.green,B(`Level ${j+1}`,`स्तर ${j+1}`));if(j<3)g.arrow([-1+j*.8,0,0],[-.65+j*.8,0,0]);for(let i=0;i<Math.min(15,factors[j]);i++)g.sphere(-1.3+j*.8+(i%5)*.05,.4+Math.floor(i/5)*.08,0,.018,C.pink)}return[read('Trophic level','पोषी स्तर',k),read('Illustrative relative concentration','सांकेतिक सापेक्ष सांद्रता',factors[k-1]),read('Meaning','अर्थ',B('Persistent pollutants can concentrate up food chains; values are illustrative','स्थायी प्रदूषक खाद्य शृंखला में ऊपर संकेंद्रित हो सकते हैं; मान सांकेतिक हैं'))]}
let plastic=extra.waste===1,remaining=plastic?1:1-k/12;g.box(0,.7,0,1,.1,.5,C.dark);for(let i=0;i<Math.round(40*remaining);i++)g.sphere(Math.sin(i*4)*.85,.4-Math.floor(i/10)*.12,Math.cos(i*3)*.35,.07,plastic?C.blue:C.green);return[read('Illustrative time','सांकेतिक समय',k,'model weeks'),read('Waste type','अपशिष्ट का प्रकार',plastic?B('Conventional plastic','सामान्य प्लास्टिक'):B('Biodegradable organic waste','जैव निम्नीकरणीय जैविक अपशिष्ट')),read('Observation','अवलोकन',plastic?B('Remains in this short illustrative period','इस छोटे सांकेतिक समय में बना रहता है'):B('Microorganisms break down organic material; actual time varies','सूक्ष्मजीव जैविक पदार्थ तोड़ते हैं; वास्तविक समय बदलता है'))]};
